17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Objects;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
108	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
109	            return new ResponseEntity<>(HttpStatus.CONFLICT);
110	        }
111	        if (owner.getRegistrationDate() == null) {
112	            owner.setRegistrationDate(LocalDate.now());
113	        }
114	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
115	        owner.setCustomerCode(generateCustomerCode(owner.getCity()));
116	        this.clinicService.saveOwner(owner);
117	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
118	        headers.setLocation(UriComponentsBuilder.newInstance()
119	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
120	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
121	    }
122	
123	    /**
124	     * Generates the customer code for a newly created owner. The code is formatted as
125	     * '&lt;UPPERCASE_CITY&gt;-&lt;NNNN&gt;' where NNNN is one more than the number of owners that
126	     * already exist in that city, zero-padded to four digits (for example 'LONDON-0007').
127	     * Cities are matched ignoring letter case.
128	     */
129	    private String generateCustomerCode(String city) {
130	        long ownersInCity = this.clinicService.findAllOwners().stream()
131	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
132	            .count();
133	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
134	    }
135	
136	    /**
137	     * Determines whether an owner already exists that uses the same telephone number
138	     * as the given one. Telephone numbers must be unique across all owners. The
139	     * comparison ignores letter case and any surrounding or repeated whitespace.
140	     */
141	    private boolean isDuplicateOwner(Owner owner) {
142	        String telephone = normalizeTelephone(owner.getTelephone());
143	        return this.clinicService.findAllOwners().stream()
144	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
145	    }
146	
147	    /**
148	     * Normalizes a telephone number for storage and comparison by stripping spaces, dashes
149	     * and parentheses so that only digits remain: for example "(613) 555-0100" becomes
150	     * "6135550100". This lets differently punctuated forms of the same number be treated as
151	     * equal for the uniqueness check and stored in a single canonical form.
152	     */
153	    private static String normalizeTelephone(String telephone) {
154	        if (telephone == null) {
155	            return null;
156	        }
157	        return telephone.replaceAll("[\\s()-]", "");
158	    }
159	
160	    /**
161	     * Determines whether another owner already uses the same email address as the given one.
162	     * Email addresses, when supplied, must be unique across all owners. An owner without an
163	     * email address is never considered a duplicate. The comparison ignores letter case and
164	     * any surrounding or repeated whitespace.
165	     */
166	    private boolean isDuplicateEmail(Owner owner) {
167	        String email = normalize(owner.getEmail());
168	        if (email == null || email.isEmpty()) {
169	            return false;
170	        }
171	        return this.clinicService.findAllOwners().stream()
172	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
173	    }
174	
175	    /**
176	     * Normalizes a user-supplied value for duplicate detection so that comparisons ignore
177	     * letter case and any surrounding or repeated whitespace: for example "  john   smith "
178	     * and "John Smith" normalize to the same key and so count as the same person.
179	     */
180	    private static String normalize(String value) {
181	        if (value == null) {
182	            return null;
183	        }
184	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
190	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
191	        if (currentOwner == null) {
192	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	        }
194	        currentOwner.setAddress(ownerFieldsDto.getAddress());
195	        currentOwner.setCity(ownerFieldsDto.getCity());
196	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
197	        currentOwner.setLastName(ownerFieldsDto.getLastName());
198	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
199	        this.clinicService.saveOwner(currentOwner);
200	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Transactional
205	    @Override
206	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
207	        Owner owner = this.clinicService.findOwnerById(ownerId);
208	        if (owner == null) {
209	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	        }
211	        this.clinicService.deleteOwner(owner);
212	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
218	        Owner owner = this.clinicService.findOwnerById(ownerId);
219	        if (owner == null) {
220	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	        }
222	        HttpHeaders headers = new HttpHeaders();
223	        Pet pet = petMapper.toPet(petFieldsDto);
224	        owner.setId(ownerId);
225	        pet.setOwner(owner);
226	        pet.getType().setName(null);
227	        this.clinicService.savePet(pet);
228	        PetDto petDto = petMapper.toPetDto(pet);
229	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
230	            .buildAndExpand(pet.getId()).toUri());
231	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
232	    }
233	
234	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
235	    @Override
236	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
237	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
238	        if (currentOwner != null) {
239	            Pet currentPet = this.clinicService.findPetById(petId);
240	            if (currentPet != null) {
241	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
242	                currentPet.setName(petFieldsDto.getName());
243	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
244	                this.clinicService.savePet(currentPet);
245	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
246	            }
247	        }
248	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
249	    }
250	
251	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
252	    @Override
253	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
254	        HttpHeaders headers = new HttpHeaders();
255	        Visit visit = visitMapper.toVisit(visitFieldsDto);
256	        Pet pet = new Pet();
257	        pet.setId(petId);
258	        visit.setPet(pet);
259	        this.clinicService.saveVisit(visit);
260	        VisitDto visitDto = visitMapper.toVisitDto(visit);
261	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
262	            .buildAndExpand(visit.getId()).toUri());
263	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
264	    }
265	
266	
267	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
268	    @Override
269	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
270	        Owner owner = this.clinicService.findOwnerById(ownerId);
271	        if (owner != null) {
272	            Pet pet = owner.getPet(petId);
273	            if (pet != null) {
274	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
275	            }
276	        }
277	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
278	    }
279	}
